#!/usr/bin/env bash
# Mints an HS256 bearer token for local development:
#   scripts/dev-token.sh olive@example.com [hours]
# It is signed with JWT_SECRET, which must match reviews.security.jwt-secret.
# Like Keycloak's tokens it carries a "role" claim, ROLE (reviewer, the
# default, or owner), and with ADMIN=1 the "admin" realm role in "roles".
set -euo pipefail

root=$(cd "$(dirname "$0")/../.." && pwd)
if [[ -z ${JWT_SECRET:-} && -f $root/.env ]]; then
  set -a
  # shellcheck source=/dev/null # Generated by scripts/secrets.sh, not in the repository.
  source "$root/.env"
  set +a
fi

email=${1:?usage: dev-token.sh EMAIL [HOURS]}
hours=${2:-8}
role=${ROLE:-reviewer}
secret=${JWT_SECRET:?JWT_SECRET is not set: run scripts/secrets.sh at the repository root}

case $email in
  *[\"\\]*) echo "dev-token.sh: email must not contain quotes or backslashes" >&2; exit 1 ;;
esac
case $role in
  reviewer | owner) ;;
  *) echo "dev-token.sh: ROLE must be reviewer or owner" >&2; exit 1 ;;
esac
roles='[]'
[[ ${ADMIN:-} == 1 ]] && roles='["admin"]'

b64url() { openssl base64 -A | tr '+/' '-_' | tr -d '='; }

now=$(date +%s)
header=$(printf '{"alg":"HS256","typ":"JWT"}' | b64url)
payload=$(printf '{"sub":"%s","email":"%s","role":"%s","roles":%s,"iat":%d,"exp":%d}' \
  "$email" "$email" "$role" "$roles" "$now" "$((now + hours * 3600))" | b64url)
signature=$(printf '%s.%s' "$header" "$payload" \
  | openssl dgst -sha256 -hmac "$secret" -binary | b64url)

printf '%s.%s.%s\n' "$header" "$payload" "$signature"
